#!/usr/bin/env bash
# ONE LINE (wraps visually here):
RG=rg-d365-demo LOC=westeurope PREFIX=d365demo SUBSCRIPTION_ID="9019cfb1-cb52-4c48-a0a8-727ad3933f34" TENANT_ID="f8054917-dc24-4ea5-9363-fa27b4814bbe" APP_ID="<your-app-client-id>" D365_HOST="<your-d365-host-url>" D365_TOKEN="<your-d365-access-token>" ; az account set --subscription $SUBSCRIPTION_ID && az group create -n $RG -l $LOC && read FUNC_NAME APIM_NAME FUNC_HOST <<< $(az deployment group create -g $RG -f infra/00-foundation.bicep -p prefix=$PREFIX --query "[properties.outputs.funcName.value,properties.outputs.apimName.value,properties.outputs.funcHostName.value]" -o tsv) && zip -r functionapp.zip functions >/dev/null && az functionapp deployment source config-zip -g $RG -n $FUNC_NAME --src functionapp.zip >/dev/null && FUNC_KEY=$(az functionapp keys list -g $RG -n $FUNC_NAME --query "functionKeys.default" -o tsv) && az deployment group create -g $RG -f infra/10-logicapp.bicep -p prefix=$PREFIX functionBaseUrl="https://$FUNC_HOST" functionKey="$FUNC_KEY" d365HostUrl="$D365_HOST" d365AccessToken="$D365_TOKEN" >/dev/null && OPENID_URL="https://login.microsoftonline.com/$TENANT_ID/v2.0/.well-known/openid-configuration" && AUDIENCE="api://$APP_ID" && az deployment group create -g $RG -f infra/20-apim.bicep -p apimName=$APIM_NAME functionHostname=$FUNC_HOST functionKey="$FUNC_KEY" openIdConfigUrl="$OPENID_URL" audience="$AUDIENCE"
